/bin/zsh -lc "node --input-type=module <<'NODE'
import assert from 'node:assert/strict';
import { readFile } from 'node:fs/promises';
import { importStock } from './src/entry.js';

const answer = JSON.parse(await readFile('answer.json', 'utf8'));
assert.deepEqual(Object.keys(answer), ['files', 'output', 'invalid_numeric', 'reserved_applied_before_clamp']);
const expectedFiles = [
  ['src/entry.js', 'importStock'],
  ['src/input/csv.js', 'parseStock'],
  ['src/domain/stock.js', 'normalizeStock'],
  ['src/domain/sku.js', 'canonicalSku'],
  ['src/output/wire.js', 'wireStock']
];
assert.deepEqual(answer.files, expectedFiles.map(([path, symbol]) => ({ path, symbol })));
for (const [path, symbol] of expectedFiles) {
  const module = await import("'`./${path}`);
  assert.equal(typeof module[symbol], '"'function');
}
assert.deepEqual(answer.output, importStock(' ab-2 ,5,8'));
assert.deepEqual(answer.output, { product_code: 'AB-2', units: 0, schema: 2 });
assert.throws(() => importStock('x,no,1'), error => error.message === answer.invalid_numeric && error.message === 'invalid count');
assert.equal(answer.reserved_applied_before_clamp, true);
assert.equal(importStock('x,9,8').units, 1);
assert.equal(importStock('x,-2,-5').units, 3);
console.log('answer.json verified against the active pipeline and requested examples');
NODE"

